#!/usr/bin/env python3
"""Regenerate data/sample/synthetic_games.csv (deterministic, SYNTHETIC data)."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from nbamodel.sample import generate_synthetic_games  # noqa: E402

out = Path(__file__).resolve().parents[1] / "data" / "sample" / "synthetic_games.csv"
out.parent.mkdir(parents=True, exist_ok=True)
with open(out, "w") as fh:
    fh.write("# SYNTHETIC DATA - simulated games between fictional teams SYN01-SYN30.\n"
             "# Not real NBA results or odds. Generated by scripts/make_sample_data.py (seed 7).\n")
    generate_synthetic_games().to_csv(fh, index=False)
print(f"wrote {out}")
